using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using UnityEngine.Rendering;using Unity.Collections;using System;using System.IO;using System.Linq;using System.Collections.Generic;
[InitializeOnLoad]public static class CubeFaceRepair{
 static CubeFaceRepair(){EditorApplication.delayCall+=Apply;EditorSceneManager.sceneSaved+=s=>EditorApplication.delayCall+=Apply;}
 class Edge{public int a,b,material;}
 static string PointKey(Vector3 p){return Math.Round(p.x,6)+","+Math.Round(p.y,6)+","+Math.Round(p.z,6);}
 static string EdgeKey(int a,int b){return Math.Min(a,b)+":"+Math.Max(a,b);}
 [MenuItem("Tools/JIQI/Repair Cube1 To Cube4 Faces")]
 public static void Apply(){if(EditorApplication.isCompiling||EditorApplication.isUpdating){EditorApplication.delayCall+=Apply;return;}if(EditorApplication.isPlayingOrWillChangePlaymode)return;
 var scene=SceneManager.GetActiveScene();if(!string.Equals(scene.name.Replace(" ",""),"scene2",StringComparison.OrdinalIgnoreCase))return;
 var all=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray();bool changed=false;var report=new List<string>();Directory.CreateDirectory("Assets/Repairs/CubeFaces");
 foreach(string name in new[]{"cube1","cube2","cube3","cube4"}){var target=all.SingleOrDefault(t=>string.Equals(t.name.Trim(),name,StringComparison.OrdinalIgnoreCase));if(!target && name=="cube4"){
 var right=all.SingleOrDefault(t=>string.Equals(t.name.Trim(),"cube2",StringComparison.OrdinalIgnoreCase));var lower=all.SingleOrDefault(t=>string.Equals(t.name.Trim(),"cube3",StringComparison.OrdinalIgnoreCase));
 var candidate=all.SingleOrDefault(t=>t.name=="立方体.024");
 if(right&&lower&&candidate&&candidate.GetComponent<Renderer>()){var expected=right.GetComponent<Renderer>().bounds.center;expected.y=lower.GetComponent<Renderer>().bounds.center.y;if(Vector3.Distance(candidate.GetComponent<Renderer>().bounds.center,expected)<1f){target=candidate;report.Add("cube4 identified as original 立方体.024 in lower-right position");}}
 }
 if(!target){report.Add(name+": not yet saved/found");continue;}var filter=target.GetComponent<MeshFilter>();if(!filter||!filter.sharedMesh){report.Add(name+": no mesh");continue;}var original=filter.sharedMesh;if(original.name.EndsWith("_FacesRepaired")){report.Add(name+": already repaired");continue;}
 try{int holes,added;Mesh repaired=Repair(original,out holes,out added);if(!repaired){report.Add(name+": already closed");continue;}var path="Assets/Repairs/CubeFaces/"+name+"_FacesRepaired.asset";var existing=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(existing){EditorUtility.CopySerialized(repaired,existing);UnityEngine.Object.DestroyImmediate(repaired);repaired=existing;}else AssetDatabase.CreateAsset(repaired,path);
 filter.sharedMesh=repaired;foreach(var collider in target.GetComponents<MeshCollider>())if(collider.sharedMesh==original){collider.sharedMesh=repaired;EditorUtility.SetDirty(collider);}EditorUtility.SetDirty(filter);changed=true;report.Add(name+": filled "+holes+" holes; added "+added+" triangles; original materials/vertices/UVs preserved");
 }catch(Exception e){report.Add(name+": "+e.Message);Debug.LogException(e);}}
 AssetDatabase.SaveAssets();if(changed){EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);}Directory.CreateDirectory("D:/-11-transfer-audit/cube-faces-20261020");File.WriteAllLines("D:/-11-transfer-audit/cube-faces-20261020/live-editor.txt",report);
 }
 public static Mesh Repair(Mesh source,out int holes,out int added){holes=0;added=0;var vertices=new List<Vector3>();var normals=new List<Vector3>();var tangents=new List<Vector4>();var colors=new List<Color>();var uv=new List<Vector4>[8];var dimensions=new int[8];var triangles=new List<int>[source.subMeshCount];
 using(var snapshot=MeshUtility.AcquireReadOnlyMeshData(source)){var data=snapshot[0];int count=data.vertexCount;using(var a=new NativeArray<Vector3>(count,Allocator.Temp)){data.GetVertices(a);vertices.AddRange(a.ToArray());if(data.HasVertexAttribute(VertexAttribute.Normal)){data.GetNormals(a);normals.AddRange(a.ToArray());}}
 if(data.HasVertexAttribute(VertexAttribute.Tangent))using(var a=new NativeArray<Vector4>(count,Allocator.Temp)){data.GetTangents(a);tangents.AddRange(a.ToArray());}
 if(data.HasVertexAttribute(VertexAttribute.Color))using(var a=new NativeArray<Color>(count,Allocator.Temp)){data.GetColors(a);colors.AddRange(a.ToArray());}
 for(int channel=0;channel<8;channel++){var attribute=(VertexAttribute)((int)VertexAttribute.TexCoord0+channel);if(!data.HasVertexAttribute(attribute))continue;dimensions[channel]=data.GetVertexAttributeDimension(attribute);using(var a=new NativeArray<Vector4>(count,Allocator.Temp)){data.GetUVs(channel,a);uv[channel]=new List<Vector4>(a.ToArray());}}
 for(int sub=0;sub<source.subMeshCount;sub++){var desc=data.GetSubMesh(sub);if(desc.topology!=MeshTopology.Triangles)throw new Exception("Non-triangle topology");triangles[sub]=new List<int>();if(source.indexFormat==IndexFormat.UInt16){var indices=data.GetIndexData<ushort>();for(int k=0;k<desc.indexCount;k++)triangles[sub].Add(indices[desc.indexStart+k]+desc.baseVertex);}else{var indices=data.GetIndexData<int>();for(int k=0;k<desc.indexCount;k++)triangles[sub].Add(indices[desc.indexStart+k]+desc.baseVertex);}}
 }
 var keys=new Dictionary<string,int>();var representative=new Dictionary<int,int>();var map=new int[vertices.Count];for(int i=0;i<vertices.Count;i++){string key=PointKey(vertices[i]);int id;if(!keys.TryGetValue(key,out id)){id=keys.Count;keys[key]=id;representative[id]=i;}map[i]=id;}
 var edges=new Dictionary<string,List<Edge>>();for(int sub=0;sub<triangles.Length;sub++)for(int i=0;i<triangles[sub].Count;i+=3)for(int j=0;j<3;j++){int a=map[triangles[sub][i+j]],b=map[triangles[sub][i+(j+1)%3]];if(a==b)continue;string key=EdgeKey(a,b);if(!edges.ContainsKey(key))edges[key]=new List<Edge>();edges[key].Add(new Edge{a=a,b=b,material=sub});}
 var boundary=edges.Values.Where(e=>e.Count==1).Select(e=>e[0]).ToArray();if(boundary.Length==0)return null;if(edges.Values.Any(e=>e.Count>2))throw new Exception("Non-manifold source; no automatic changes made");
 var outgoing=boundary.GroupBy(e=>e.a).ToDictionary(g=>g.Key,g=>g.ToArray());if(outgoing.Values.Any(e=>e.Length!=1))throw new Exception("Branched boundary; no automatic changes made");var visited=new HashSet<int>();
 foreach(var start in boundary){if(visited.Contains(start.a))continue;var loop=new List<int>();var materials=new List<int>();int current=start.a;do{if(visited.Contains(current)||!outgoing.ContainsKey(current))throw new Exception("Broken boundary");visited.Add(current);loop.Add(representative[current]);materials.Add(outgoing[current][0].material);current=outgoing[current][0].b;}while(current!=start.a);
 loop.Reverse();var points=loop.Select(i=>vertices[i]).ToArray();var center=points.Aggregate(Vector3.zero,(a,b)=>a+b)/points.Length;float scale=points.Max(p=>Vector3.Distance(p,center));if(scale<1e-7f)throw new Exception("Degenerate boundary");Vector3 normal=Vector3.zero;for(int i=0;i<points.Length;i++)normal+=Vector3.Cross((points[i]-center)/scale,(points[(i+1)%points.Length]-center)/scale);normal.Normalize();if(normal.sqrMagnitude<.5f)throw new Exception("Undefined cap normal");if(points.Any(p=>Mathf.Abs(Vector3.Dot(p-center,normal))>scale*.001f))throw new Exception("Non-planar hole needs manual topology");
 // Leave local +Z drawer tops open.
 if(normal.z>.99f && points.All(p=>Mathf.Abs(p.z-source.bounds.max.z)<1e-6f))continue;
 Vector3 axis=(points.OrderByDescending(p=>(p-center).sqrMagnitude).First()-center).normalized;Vector3 second=Vector3.Cross(normal,axis).normalized;var projected=points.Select(p=>new Vector2(Vector3.Dot(p-center,axis)/scale,Vector3.Dot(p-center,second)/scale)).ToArray();var cap=Triangulate(projected);int first=vertices.Count;var minimum=new Vector2(projected.Min(p=>p.x),projected.Min(p=>p.y));var maximum=new Vector2(projected.Max(p=>p.x),projected.Max(p=>p.y));
 for(int i=0;i<loop.Count;i++){vertices.Add(points[i]);if(normals.Count>0)normals.Add(normal);if(tangents.Count>0)tangents.Add(new Vector4(axis.x,axis.y,axis.z,1));if(colors.Count>0)colors.Add(colors[loop[i]]);for(int channel=0;channel<8;channel++)if(uv[channel]!=null)uv[channel].Add(new Vector4((projected[i].x-minimum.x)/Mathf.Max(.001f,maximum.x-minimum.x),(projected[i].y-minimum.y)/Mathf.Max(.001f,maximum.y-minimum.y),0,0));}
 int material=materials.GroupBy(i=>i).OrderByDescending(g=>g.Count()).First().Key;foreach(int index in cap)triangles[material].Add(first+index);holes++;added+=cap.Count/3;
 }
 var mesh=UnityEngine.Object.Instantiate(source);mesh.name=source.name+"_FacesRepaired";mesh.SetVertices(vertices);if(normals.Count>0)mesh.SetNormals(normals);if(tangents.Count>0)mesh.SetTangents(tangents);if(colors.Count>0)mesh.SetColors(colors);
 for(int channel=0;channel<8;channel++)if(uv[channel]!=null){if(dimensions[channel]<=2)mesh.SetUVs(channel,uv[channel].Select(p=>new Vector2(p.x,p.y)).ToList());else if(dimensions[channel]==3)mesh.SetUVs(channel,uv[channel].Select(p=>new Vector3(p.x,p.y,p.z)).ToList());else mesh.SetUVs(channel,uv[channel]);}
 mesh.subMeshCount=triangles.Length;for(int i=0;i<triangles.Length;i++)mesh.SetTriangles(triangles[i],i);if(normals.Count==0)mesh.RecalculateNormals();mesh.RecalculateBounds();return mesh;
 }
 static float Cross(Vector2 a,Vector2 b,Vector2 c){return (b.x-a.x)*(c.y-a.y)-(b.y-a.y)*(c.x-a.x);}
 static List<int> Triangulate(Vector2[] points){var remaining=Enumerable.Range(0,points.Length).ToList();var result=new List<int>();while(remaining.Count>3){bool found=false;for(int k=0;k<remaining.Count;k++){int a=remaining[(k+remaining.Count-1)%remaining.Count],b=remaining[k],c=remaining[(k+1)%remaining.Count];if(Cross(points[a],points[b],points[c])<=1e-8f)continue;bool contains=remaining.Any(j=>j!=a&&j!=b&&j!=c&&Cross(points[a],points[b],points[j])>=-1e-8f&&Cross(points[b],points[c],points[j])>=-1e-8f&&Cross(points[c],points[a],points[j])>=-1e-8f);if(contains)continue;result.AddRange(new[]{a,b,c});remaining.RemoveAt(k);found=true;break;}if(!found)throw new Exception("Cannot triangulate boundary without distortion");}result.AddRange(remaining);return result;}
}
